failure.message:
1. Test Case ID: LiFfor

- API accepts invalid authentication

    Expected 401, got `200 OK` for `GET /api/v1/grupos-requisitante` (generated auth likely invalid)

- Response violates schema

    "idCliente" is a required property

    Schema at /components/schemas/GrupoOutput:

        {
            "required": [
                "id",
                "idCliente",
                "nome",
                "descricao",
                "ativo"
            ],
            "type": "object",
            "properties": {
                "id": {
                    "type": "string",
                    "format": "uuid",
                    "example": "6739f533-5bde-486a-a9b4-9af5605b51fb"
                },
                "idCliente": {
                    "type": "string",
                    "format": "uuid",
                    "example": "b1c2d3e4-f5a6-7890-bcde-fa1234567890"
                },
                "nome": {
                    "type": "string",
                    "example": "Grupo de Assinatura"
                },
                "descricao": {
                    "type": "string",
                    "example": "Grupo respons\u00e1vel por assinaturas de contratos."
                },
                "ativo": {
                    "type": "boolean",
                    "example": true
                },
                "gestores": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    },
                    "example": [
                        "6739f533-5bde-486a-a9b4-9af5605b51fb"
                    ]
                },
                "requisitantes": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    },
                    "example": [
                        "b1c2d3e4-f5a6-7890-bcde-fa1234567890"
                    ]
                },
                "preferencias": {
                    "$ref": "#/components/schemas/PreferenciasGrupoOutput"
                }
            }
        }

    Value:

        {
            "id": "a2b0255c-82ed-44b3-911d-3100e5758a65",
            "nome": "GR2"
        }

[200] OK:

    `[{"id":"a2b0255c-82ed-44b3-911d-3100e5758a65","nome":"GR2"},{"id":"19677acb-74f4-4bc3-ab1c-d3e6ba4ad88d","nome":"GR3"},{"id":"0eabb1d3-6a31-4067-b945-72fb9c5a0ac2","nome":"GR4"}]`

Reproduce with:

    curl -X GET -H 'Authorization: [Filtered]' -H 'Cookie: [Filtered]' http://localhost/api/v1/grupos-requisitante
